 private void fuselage(){float[]z={-6.2f,-5.4f,-4.5f,-3.5f,-2.5f,-1.4f,-.2f,1,2.1f,3.15f};float[]rx={.05f,.20f,.42f,.72f,1.02f,1.18f,1.26f,1.24f,1.08f,.70f};float[]ry={.05f,.16f,.30f,.48f,.62f,.70f,.72f,.68f,.58f,.40f};for(int s=0;s<z.length-1;s++)for(int i=0;i<24;i++){double a=2*Math.PI*i/24,b=2*Math.PI*(i+1)/24;quad(v(rx[s]*cos(a),.05f+ry[s]*sin(a),z[s]),v(rx[s+1]*cos(a),.05f+ry[s+1]*sin(a),z[s+1]),v(rx[s+1]*cos(b),.05f+ry[s+1]*sin(b),z[s+1]),v(rx[s]*cos(b),.05f+ry[s]*sin(b),z[s]));}part=PART_UPPER_PANEL;prism(new float[][]{{-.48f,.61f,-2.8f},{.48f,.61f,-2.8f},{.75f,.80f,-1.4f},{.74f,.82f,.5f},{.50f,.67f,2.5f},{-.50f,.67f,2.5f},{-.74f,.82f,.5f},{-.75f,.80f,-1.4f}},.06f);part=PART_SKIN;}
