 private void canopyFrame(){prism(new float[][]{{-.43f,.80f,-2.15f},{.43f,.80f,-2.15f},{.38f,.90f,-1.94f},{-.38f,.90f,-1.94f}},.05f);prism(new float[][]{{-.51f,.83f,-1.05f},{.51f,.83f,-1.05f},{.45f,.98f,-.88f},{-.45f,.98f,-.88f}},.045f);prism(new float[][]{{-.52f,.79f,-2.02f},{-.43f,.82f,.62f},{-.36f,.79f,.82f},{-.46f,.77f,-2.02f}},.04f);prism(new float[][]{{.46f,.77f,-2.02f},{.36f,.79f,.82f},{.43f,.82f,.62f},{.52f,.79f,-2.02f}},.04f);}
 private void gearStruts(){tubeBetween(0,-.55f,-3.72f,0,-1.48f,-3.72f,.075f);tubeBetween(-.14f,-1.42f,-3.72f,-.14f,-1.68f,-3.72f,.045f);tubeBetween(.14f,-1.42f,-3.72f,.14f,-1.68f,-3.72f,.045f);for(float s:new float[]{-1,1}){float wx=1.68f*s;tubeBetween(.88f*s,-.48f,.52f,1.42f*s,-1.30f,.94f,.095f);tubeBetween(1.10f*s,-.62f,1.30f,1.42f*s,-1.30f,.94f,.055f);tubeBetween(1.42f*s,-1.30f,.94f,wx,-1.58f,1.10f,.070f);tubeBetween(wx,-1.45f,.91f,wx,-1.67f,1.10f,.045f);}}
